import { expr } from "../../engine/tf/index.js";
const CATEGORY_RESOURCE_TYPE = "elementum_category";
/** Resource ID when the category is created in this apply; otherwise a live data lookup. */
export function categoryIdExpr(resolved) {
    return resolved.managed === true
        ? expr.resourceAttr(CATEGORY_RESOURCE_TYPE, resolved.tfLabel, ["id"])
        : expr.dataAttr(CATEGORY_RESOURCE_TYPE, resolved.tfLabel, ["id"]);
}
export function missingCategoryDiagnostic(name) {
    return (`category ${JSON.stringify(name)} is not in organization.ts or the org catalog — ` +
        `add it to organization.ts (same apply) or re-run \`elementum pull org --data-only\``);
}
